const s = $input.first().json;
const ex = $('Extract Facts').first().json;
const th = s.thresholds || {};
const reasons = [];

const intent = ex.intent || 'unclear';
if (intent === 'request_human') reasons.push('request_human');

const unparsedLimit = typeof th.escalate_unparsed_streak === 'number' ? th.escalate_unparsed_streak : 2;
const repeatLimit = typeof th.escalate_repeat_streak === 'number' ? th.escalate_repeat_streak : 2;
if ((s.unparsed_streak || 0) >= unparsedLimit) reasons.push('unparsed_streak');
if ((s.repeat_streak || 0) >= repeatLimit) reasons.push('repeat_streak');

const budget = s.budget;
const budgetMin = (budget && typeof budget === 'object' && typeof budget.min === 'number') ? budget.min : null;
const pm = s.payment_method === null || s.payment_method === undefined ? null : String(s.payment_method);
const highValueMin = typeof th.escalate_high_value_min_budget === 'number' ? th.escalate_high_value_min_budget : null;
const highValueMethods = Array.isArray(th.escalate_high_value_payment_methods) ? th.escalate_high_value_payment_methods : [];
if (budgetMin !== null && highValueMin !== null && budgetMin >= highValueMin && pm !== null && highValueMethods.indexOf(pm) !== -1) {
  reasons.push('high_value');
}

return [{ json: {
  escalate: reasons.length > 0,
  reason: reasons.join(','),
  intent: intent,
  question_text: ex.question_text || ''
} }];

const cfg = $('Gather Unprocessed Messages').first().json;
const d = $('Decide Next Step').first().json;
const nl = String.fromCharCode(10);

let answerText = '';
let grounded = false;
try {
  const a = $('Answer Question').first().json;
  answerText = a.answer_text || '';
  grounded = a.grounded === true;
} catch (e) { answerText = ''; grounded = false; }

const history = Array.isArray(cfg.history) ? cfg.history : [];
// The composer has to know it is opening a conversation, or it treats "hi" as
// an answer to something and reaches for wording written for a lead who arrived
// already talking about a project.
const isFirstTurn = history.filter(function (h) { return h && h.direction === 'outbound'; }).length === 0;

const filled = (cfg.filled_values && typeof cfg.filled_values === 'object') ? cfg.filled_values : {};
const namedContext = String(filled.project_interest || '');

// The budget on file is a widened search band, not what the lead said, so only
// their own words are ever put in front of the composer.
const known = {};
for (const k of Object.keys(filled)) {
  const v = filled[k];
  if (k === 'budget' && v && typeof v === 'object') { known[k] = v.stated_text ? v.stated_text : 'already given'; }
  else if (v && typeof v === 'object') { known[k] = JSON.stringify(v); }
  else { known[k] = v; }
}

const question = String(d.question_text || '').trim();

return [{ json: {
  action: d.action || 'ask_slot',
  goal: String(d.goal || question),
  facts_json: '[]',
  known_json: JSON.stringify(known),
  is_first_turn: isFirstTurn,
  lead_named_context: namedContext,
  answer_text: answerText,
  grounded: grounded,
  choices_json: d.choices_json || '[]',
  variant: d.variant || '',
  history_json: JSON.stringify(history),
  language: cfg.language || 'en',
  lead_last_message: cfg.combined_text || '',
  fallback_text: (answerText ? answerText + nl + nl : '') + question,
  slot_key: d.slot_key || '',
  asked_slot: true
} }];

const cfg = $('Gather Unprocessed Messages').first().json;
const d = $('Decide Next Step').first().json;
const r = $input.first().json;
const lines = cfg.lines || {};
const lang = cfg.language || 'en';
const nl = String.fromCharCode(10);
function line(key, fallback) { const l = lines[key] || {}; return l[lang] || l.en || fallback; }

let answerText = '';
let grounded = false;
