} catch (e) { answerText = ''; grounded = false; }

const history = Array.isArray(cfg.history) ? cfg.history : [];
const isFirstTurn = history.filter(function (h) { return h && h.direction === 'outbound'; }).length === 0;

const filled = (cfg.filled_values && typeof cfg.filled_values === 'object') ? cfg.filled_values : {};
const namedContext = String(filled.project_interest || '');
const known = {};
for (const k of Object.keys(filled)) {
  const v = filled[k];
  if (k === 'budget' && v && typeof v === 'object') { known[k] = v.stated_text ? v.stated_text : 'already given'; }
  else if (v && typeof v === 'object') { known[k] = JSON.stringify(v); }
  else { known[k] = v; }
}

const slots = Array.isArray(r.slots) ? r.slots : [];
// The labels are the only quotable things here. The composer must reproduce
// them character for character or Validate Reply drops back to the template.
const labels = slots.map(function (s) { return String(s.label_local || ''); }).filter(function (l) { return l.length > 0; });
const listed = labels.map(function (l, i) { return (i + 1) + '. ' + l; }).join(nl);
const fallback = (answerText ? answerText + nl + nl : '') + line('offer_line', 'Here are the next few times the agent is free:') + nl + listed + nl + line('offer_prompt_line', 'Just tell me which one suits you.');

const action = (d.action === 'reoffer_booking') ? 'reoffer_booking' : 'offer_booking';

return [{ json: {
  action: action,
  goal: String(d.goal || 'offer the times listed and ask which one suits them'),
  facts_json: JSON.stringify(labels),
  known_json: JSON.stringify(known),
  is_first_turn: isFirstTurn,
  lead_named_context: namedContext,
  answer_text: answerText,
  grounded: grounded,
  choices_json: '[]',
  variant: d.variant || '',
  history_json: JSON.stringify(history),
  language: lang,
  lead_last_message: cfg.combined_text || '',
  fallback_text: fallback,
  slot_key: '',
  asked_slot: false
} }];

